#include "compositors/niri/niri_layout_theme.h"

#include "compositors/niri/niri_config_files.h"

namespace compositors::niri {
  namespace {

    constexpr std::string_view kManagedHeader =
        "// Generated by Noctalia from Settings → Theme. Edits here are overwritten.\n"
        "// Only one `layout` block should exist across your niri config and its includes;\n"
        "// remove any other focus-ring/border settings so this one applies cleanly.\n";

    void appendRingOrBorder(
        std::string& out, std::string_view node, bool enabled, std::string_view activeHex,
        std::string_view inactiveHex
    ) {
      out += "    ";
      out += node;
      out += " {\n";
      if (!enabled) {
        out += "        off\n";
      }
      out += "        active-color \"";
      out += activeHex;
      out += "\"\n        inactive-color \"";
      out += inactiveHex;
      out += "\"\n    }\n";
    }

  } // namespace

  std::filesystem::path layoutThemeIncludePath() { return includePath(kLayoutThemeIncludeFileName); }

  std::string kdlForLayoutTheme(const LayoutThemeSettings& settings) {
    std::string body(kManagedHeader);
    body += "layout {\n";
    appendRingOrBorder(body, "focus-ring", settings.focusRing, settings.activeColorHex, settings.inactiveColorHex);
    appendRingOrBorder(body, "border", settings.border, settings.activeColorHex, settings.inactiveColorHex);
    body += "}\n";
    return body;
  }

  InstallResult saveNiriLayoutTheme(const LayoutThemeSettings& settings) {
    return saveNiriLayoutThemeInto(configPath(), settings);
  }

  InstallResult saveNiriLayoutThemeInto(const std::filesystem::path& configFile, const LayoutThemeSettings& settings) {
    InstallResult result;
    if (configFile.empty()) {
      result.error = "niri config path is unknown";
      return result;
    }
    std::error_code ec;
    if (!std::filesystem::exists(configFile, ec) || ec) {
      result.error = "niri config not found";
      return result;
    }
    const auto include = configFile.parent_path() / std::string(kLayoutThemeIncludeFileName);
    if (!writeFile(include, kdlForLayoutTheme(settings), result.error)) {
      return result;
    }
    if (!appendInclude(configFile, kLayoutThemeIncludeFileName, result.error)) {
      return result;
    }
    result.ok = true;
    result.added = 1;
    return result;
  }

} // namespace compositors::niri
